.detail-section-title{font-size:15px;margin:22px 0 12px}.order-info{table-layout:fixed;margin-bottom:20px}.order-info th{width:130px;font-weight:600;white-space:normal}.order-info td{max-width:none;white-space:pre-wrap;line-height:1.7}.detail-overlay{position:fixed;inset:0;z-index:50;display:grid;place-items:center;padding:24px;background:#183b3566}.order-detail{box-sizing:border-box;width:min(1000px,100%);max-height:90dvh;overflow:auto;overscroll-behavior:contain;padding:26px;border:1px solid #c7dbce;border-radius:16px;background:#fff;color:#243b39;box-shadow:0 20px 70px #173c3533}.order-detail:focus{outline:none}@media(max-width:650px){.detail-overlay{padding:10px}.order-detail{padding:16px}}.table-actions{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:10px}.success{padding:14px;background:#e6f4e9;color:#256e42;border-radius:10px}.dashboard{padding:28px 32px;overflow:auto;background:#f5f7f3;flex:1;color:#243b39;min-width:0}.dashboard-header{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.eyebrow{color:#258574;font-size:12px;letter-spacing:2px;margin:0 0 8px}h1{margin:0;font-size:30px}h2{font-size:17px;margin:0 0 18px}.subtitle,.note{font-size:13px;color:#697d76;line-height:1.7}.refresh{display:flex;align-items:center;gap:12px;white-space:nowrap}.refresh small{color:#697d76}button{border:1px solid #c7ddd5;border-radius:8px;padding:9px 14px;background:#fff;color:#237d6d;cursor:pointer;font:inherit;font-size:13px}button:hover{background:#eaf4ef}button:disabled{opacity:.45;cursor:not-allowed}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}.metric{text-align:left;display:flex;flex-direction:column;gap:12px;padding:20px;background:#fff;border:1px solid #e0e9e0;border-radius:14px;color:#48645c}.metric strong{font-size:27px;color:#183f35;font-variant-numeric:tabular-nums}.metric small{font-size:11px;color:#6e9183}.chart-grid{display:grid;grid-template-colu